{"id":"bcba43d3-1966-4533-b4e1-83fd75eadbc0","inserted_at":"2026-07-07T12:58:58.381472+00:00","updated_at":"2026-07-07T12:58:58.381472+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- Migration V18: Whitelabel Core & Security (RLS)\r\n\r\n-- 1. Create tenants table (replacing territories)\r\nDROP TABLE IF EXISTS public.territories CASCADE;\r\nCREATE TABLE IF NOT EXISTS public.tenants (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    slug VARCHAR(50) UNIQUE NOT NULL,\r\n    name VARCHAR(255) NOT NULL,\r\n    center JSONB NOT NULL,\r\n    boundaries JSONB NOT NULL,\r\n    mapbox_style VARCHAR(255) DEFAULT 'mapbox://styles/mapbox/streets-v11',\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\r\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\r\n);\r\n\r\n-- 2. Create tenant_localizations table\r\nCREATE TABLE IF NOT EXISTS public.tenant_localizations (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    tenant_id UUID REFERENCES public.tenants(id) ON DELETE CASCADE,\r\n    language_code VARCHAR(10) DEFAULT 'it',\r\n    colors JSONB NOT NULL,\r\n    assets JSONB NOT NULL,\r\n    ticker_text TEXT,\r\n    pti_name VARCHAR(50) DEFAULT 'PTI',\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\r\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\r\n    UNIQUE(tenant_id, language_code)\r\n);\r\n\r\n-- 3. Create tenant_events table\r\nCREATE TABLE IF NOT EXISTS public.tenant_events (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    tenant_id UUID REFERENCES public.tenants(id) ON DELETE CASCADE,\r\n    title VARCHAR(255) NOT NULL,\r\n    description TEXT,\r\n    event_date TIMESTAMP WITH TIME ZONE NOT NULL,\r\n    location_coords GEOGRAPHY(POINT),\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\r\n);\r\n\r\n-- 4. Create tenant_associations table\r\nCREATE TABLE IF NOT EXISTS public.tenant_associations (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    tenant_id UUID REFERENCES public.tenants(id) ON DELETE CASCADE,\r\n    name VARCHAR(255) NOT NULL,\r\n    role VARCHAR(50) DEFAULT 'partner',\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\r\n);\r\n\r\n-- 5. Create civic_reports table\r\nDROP TABLE IF EXISTS public.civic_reports CASCADE;\r\nCREATE TABLE public.civic_reports (\r\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\r\n    profile_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE,\r\n    tenant_id UUID REFERENCES public.tenants(id) ON DELETE CASCADE,\r\n    report_type VARCHAR(50) NOT NULL,\r\n    description TEXT,\r\n    status VARCHAR(50) DEFAULT 'pending',\r\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\r\n);\r\n\r\n-- ==========================================\r\n-- ROW LEVEL SECURITY (RLS) POLICIES\r\n-- ==========================================\r\n\r\n-- Enable RLS\r\nALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.tenant_localizations ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.tenant_events ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.tenant_associations ENABLE ROW LEVEL SECURITY;\r\nALTER TABLE public.civic_reports ENABLE ROW LEVEL SECURITY;\r\n\r\n-- Tenants: Public read\r\nDROP POLICY IF EXISTS \"Tenants are viewable by everyone\" ON public.tenants;\r\nCREATE POLICY \"Tenants are viewable by everyone\" ON public.tenants FOR SELECT USING (true);\r\n\r\n-- Tenant Localizations: Public read\r\nDROP POLICY IF EXISTS \"Tenant localizations are viewable by everyone\" ON public.tenant_localizations;\r\nCREATE POLICY \"Tenant localizations are viewable by everyone\" ON public.tenant_localizations FOR SELECT USING (true);\r\n\r\n-- Tenant Events: Public read\r\nDROP POLICY IF EXISTS \"Tenant events are viewable by everyone\" ON public.tenant_events;\r\nCREATE POLICY \"Tenant events are viewable by everyone\" ON public.tenant_events FOR SELECT USING (true);\r\n\r\n-- Tenant Associations: Public read\r\nDROP POLICY IF EXISTS \"Tenant associations are viewable by everyone\" ON public.tenant_associations;\r\nCREATE POLICY \"Tenant associations are viewable by everyone\" ON public.tenant_associations FOR SELECT USING (true);\r\n\r\n-- Civic Reports: Users see their own, Admins see all\r\nDROP POLICY IF EXISTS \"Users can view their own reports\" ON public.civic_reports;\r\nCREATE POLICY \"Users can view their own reports\" ON public.civic_reports FOR SELECT USING (auth.uid() = profile_id);\r\n\r\nDROP POLICY IF EXISTS \"Users can insert their own reports\" ON public.civic_reports;\r\nCREATE POLICY \"Users can insert their own reports\" ON public.civic_reports FOR INSERT WITH CHECK (auth.uid() = profile_id);\r\n\r\n-- Esempio di policy admin (dipende da come gestisci i ruoli, es. tramite custom JWT claims)\r\n-- Se usi il service_role di Supabase dal backend per il pannello admin, questa policy non è strettamente necessaria \r\n-- in quanto il service_role bypassa le RLS. Ma se l'admin accede dall'app, ecco un approccio standard:\r\nDROP POLICY IF EXISTS \"Admins can view all reports\" ON public.civic_reports;\r\nCREATE POLICY \"Admins can view all reports\" ON public.civic_reports FOR SELECT USING (auth.jwt() ->> 'role' = 'admin');\r\n","content_id":"bcba43d3-1966-4533-b4e1-83fd75eadbc0","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
